ALTER TABLE public.campaign_letters ADD COLUMN deleted_at timestamptz, ADD COLUMN deleted_by uuid;
CREATE TABLE public.letter_rounds(number integer PRIMARY KEY, closed boolean NOT NULL DEFAULT false, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.letter_rounds TO authenticated; GRANT ALL ON public.letter_rounds TO service_role;
ALTER TABLE public.letter_rounds ENABLE ROW LEVEL SECURITY;
CREATE POLICY rounds_read ON public.letter_rounds FOR SELECT TO authenticated USING(true);
INSERT INTO public.letter_rounds(number,closed) SELECT DISTINCT letter_number,false FROM public.campaign_letters WHERE letter_number IS NOT NULL ON CONFLICT DO NOTHING;
CREATE FUNCTION public.open_letter_round() RETURNS integer LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT max(number) FROM public.letter_rounds WHERE NOT closed $$;
CREATE FUNCTION public.set_letter_round(p_number integer,p_closed boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_campaign_admin() THEN RAISE EXCEPTION 'Somente o Narrador abre ou fecha missivas'; END IF; IF NOT p_closed THEN UPDATE public.letter_rounds SET closed=true,updated_at=now() WHERE number<>p_number; END IF; INSERT INTO public.letter_rounds(number,closed) VALUES(p_number,p_closed) ON CONFLICT(number) DO UPDATE SET closed=excluded.closed,updated_at=now(); END $$;
CREATE OR REPLACE FUNCTION public.can_read_letter(l public.campaign_letters) RETURNS boolean LANGUAGE sql STABLE SET search_path=public AS $$ SELECT public.is_campaign_admin() OR (l.deleted_at IS NULL AND (l.sender_user_id=auth.uid() OR coalesce(public.letter_recipient(l),false))) $$;
CREATE FUNCTION public.delete_campaign_letter(p_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE l public.campaign_letters; BEGIN SELECT * INTO l FROM public.campaign_letters WHERE id=p_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Missiva não encontrada'; END IF; IF NOT (public.is_campaign_admin() OR l.sender_user_id=auth.uid()) THEN RAISE EXCEPTION 'Só quem enviou pode excluir esta missiva'; END IF; UPDATE public.campaign_letters SET deleted_at=now(),deleted_by=auth.uid() WHERE id=p_id; END $$;
CREATE FUNCTION public.player_send_letter_to(p_subject text,p_content text,p_house text,p_key uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE pid uuid; hid text; pname text; lid uuid; n integer; BEGIN pid:=public.my_player_id(); IF pid IS NULL THEN RAISE EXCEPTION 'Sua conta ainda não está vinculada a um jogador autorizado'; END IF; SELECT m.house_id INTO hid FROM public.house_memberships m WHERE m.player_id=pid LIMIT 1; IF hid IS NULL THEN RAISE EXCEPTION 'Nenhuma casa autorizada para esta conta'; END IF; n:=public.open_letter_round(); IF n IS NULL THEN RAISE EXCEPTION 'Missivas fechadas, aguarde o narrador abrir a próxima semana'; END IF; IF btrim(p_subject)='' OR btrim(p_content)='' THEN RAISE EXCEPTION 'Preencha assunto e conteúdo'; END IF; IF p_house IS NOT NULL AND (p_house=hid OR NOT EXISTS(SELECT 1 FROM public.campaign_houses WHERE id=p_house AND active AND season=2)) THEN RAISE EXCEPTION 'Casa destinatária inválida'; END IF; SELECT id INTO lid FROM public.campaign_letters WHERE id=p_key AND sender_user_id=auth.uid(); IF FOUND THEN RETURN lid; END IF; SELECT name INTO pname FROM public.campaign_players WHERE id=pid; INSERT INTO public.campaign_letters(id,sender_user_id,sender_player_id,sender_name,recipient_player_id,recipient_house_id,subject,content,letter_kind,letter_number) VALUES(p_key,auth.uid(),pid,coalesce(pname,'Jogador'),NULL,p_house,p_subject,p_content,'reservada',n) RETURNING id INTO lid; RETURN lid; END $$;
CREATE OR REPLACE FUNCTION public.reply_campaign_letter(p_letter uuid,p_content text,p_key uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE l public.campaign_letters; rid uuid; pname text; BEGIN SELECT * INTO l FROM public.campaign_letters WHERE id=p_letter FOR UPDATE; IF NOT FOUND OR l.deleted_at IS NOT NULL OR NOT (coalesce(public.letter_recipient(l),false) OR public.is_campaign_admin()) THEN RAISE EXCEPTION 'Você não é destinatário desta missiva'; END IF; IF NOT public.is_campaign_admin() AND public.open_letter_round() IS NULL THEN RAISE EXCEPTION 'Missivas fechadas, aguarde o narrador abrir a próxima semana'; END IF; IF btrim(p_content)='' THEN RAISE EXCEPTION 'Escreva a resposta'; END IF; SELECT id INTO rid FROM public.letter_replies WHERE author_user_id=auth.uid() AND idempotency_key=p_key; IF FOUND THEN RETURN rid; END IF; IF public.is_campaign_admin() THEN pname:='Mestre'; ELSE SELECT name INTO pname FROM public.campaign_players WHERE id=public.my_player_id(); END IF; INSERT INTO public.letter_replies(letter_id,author_user_id,author_player_id,author_name,house_id,recipient_user_id,content,idempotency_key) VALUES(l.id,auth.uid(),public.my_player_id(),coalesce(pname,'Jogador'),l.recipient_house_id,l.sender_user_id,p_content,p_key) RETURNING id INTO rid; INSERT INTO public.letter_receipts(letter_id,user_id) VALUES(l.id,auth.uid()) ON CONFLICT DO NOTHING; RETURN rid; END $$;
CREATE OR REPLACE FUNCTION public.player_send_letter(p_subject text,p_content text,p_key uuid) RETURNS uuid LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ SELECT public.player_send_letter_to(p_subject,p_content,NULL,p_key) $$;
REVOKE ALL ON FUNCTION public.open_letter_round(),public.set_letter_round(integer,boolean),public.delete_campaign_letter(uuid),public.player_send_letter_to(text,text,text,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.open_letter_round(),public.set_letter_round(integer,boolean),public.delete_campaign_letter(uuid),public.player_send_letter_to(text,text,text,uuid) TO authenticated;
ALTER PUBLICATION supabase_realtime ADD TABLE public.letter_rounds;